export const TRASH_SACK_START = '2026-10-09';
export const TRASH_SACK_SKU = 'SACOS-BASURA-100L';
export const isTrashSack = (product: { name?: unknown; sku?: unknown }) =>
  product.sku === TRASH_SACK_SKU || /^sacos? (?:de )?basura 100\s*l$/i.test(String(product.name ?? '').trim());

// Historical exports/costs keep the agreed service-date boundary.
export function trashSackQuantity(property: Record<string, unknown> | null | undefined, date: string): number {
  if (date < TRASH_SACK_START) return 0;
  return preparationTrashSackQuantity(property);
}

// Every bag prepared from the 08/10 rollout needs its configured sacks,
// including overdue services. Preparation is independent of accounting dates.
export function preparationTrashSackQuantity(property: Record<string, unknown> | null | undefined): number {
  const rules = property?.stock_property_consumption_rules;
  if (!Array.isArray(rules)) return 0;
  return rules.reduce((total, rule) => {
    const product = rule.stock_products;
    const quantity = Number(rule.quantity_per_cleaning);
    return rule.is_active && product?.is_active && product?.is_consumable &&
      product.sede_id === property?.sede_id && isTrashSack(product) && Number.isSafeInteger(quantity) && quantity >= 0
      ? total + quantity : total;
  }, 0);
}

type Content = Record<string, unknown>;

const quantities = (value: unknown) => Object.entries(
  value && typeof value === 'object' ? value as Content : {},
).map(([key, quantity]) => [key, Number(quantity) || 0] as const)
  .filter(([, quantity]) => quantity !== 0)
  .sort(([a], [b]) => a.localeCompare(b));

// Operational metadata (cleaner, cleaning status, times) never changes a bag.
export function bagRequirementsSignature(content: Content): string {
  return JSON.stringify({
    propertyId: content.propertyId ?? '',
    textiles: quantities(content.textiles),
    amenities: quantities(content.amenities),
  });
}

export function bagRequirementsChanged(previous: Content | null, current: Content): boolean {
  if (!previous) return false;
  if (bagRequirementsSignature(previous) !== bagRequirementsSignature(current)) return true;
  // Older snapshots did not store stock rules. Establish their baseline without
  // asking workers to prepare all previously completed bags again on rollout.
  if (!Array.isArray(previous.stockConsumables)) return false;
  const stock = (content: Content) => (Array.isArray(content.stockConsumables) ? content.stockConsumables : [])
    .map((item: Content) => [String(item.productId), Number(item.quantity) || 0])
    .sort(([a], [b]) => String(a).localeCompare(String(b)));
  return JSON.stringify(stock(previous)) !== JSON.stringify(stock(current));
}

export type RouteWorkerIdentity = {
  routeWorkerId: string;
  cleanerId: string;
  workerName: string;
  sedeId: string;
};

export type RouteWorkerOption = {
  id: string;
  cleanerId: string;
  name: string;
  sedeId: string;
};

type SupabaseLike = any;

function singleRelation<T>(value: T | T[] | null | undefined): T | null {
  if (Array.isArray(value)) return value[0] ?? null;
  return value ?? null;
}

export async function sha256(value: string): Promise<string> {
  const bytes = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return Array.from(new Uint8Array(digest))
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join('');
}

export async function getRouteLink(supabase: SupabaseLike, token: string) {
  const { data: link, error } = await supabase
    .from('laundry_share_links')
    .select('id, token, sede_id, workflow_version, is_active, expires_at')
    .eq('token', token)
    .eq('is_active', true)
    .maybeSingle();

  if (error) throw error;
  if (!link) return { error: 'Enlace no valido', status: 404 } as const;
  if (link.workflow_version !== 'route_v2') {
    return { error: 'El acceso por PIN solo esta disponible en el nuevo sistema de ruta', status: 400 } as const;
  }
  if (link.expires_at && new Date(link.expires_at) < new Date()) {
    return { error: 'Enlace expirado', status: 410 } as const;
  }
  if (!link.sede_id) return { error: 'La ruta no tiene una sede configurada', status: 409 } as const;
  return { link } as const;
}

export async function listActiveRouteWorkers(
  supabase: SupabaseLike,
  sedeId: string,
): Promise<RouteWorkerOption[]> {
  const { data, error } = await supabase
    .from('laundry_route_workers')
    .select('id, cleaner_id, sede_id, cleaners!inner(id, name, is_active)')
    .eq('sede_id', sedeId)
    .eq('is_active', true)
    .eq('cleaners.is_active', true);

  if (error) throw error;
  return (data ?? [])
    .map((row: any) => {
      const cleaner = singleRelation(row.cleaners as { name?: string } | Array<{ name?: string }> | null);
      return {
        id: String(row.id),
        cleanerId: String(row.cleaner_id),
        name: String(cleaner?.name ?? 'Repartidor'),
        sedeId: String(row.sede_id),
      };
    })
    .sort((a: { name: string }, b: { name: string }) =>
      a.name.localeCompare(b.name, 'es', { sensitivity: 'base' })
    );
}

export async function validateRouteSession(
  supabase: SupabaseLike,
  shareLinkId: string,
  rawSessionToken: string,
): Promise<RouteWorkerIdentity | null> {
  if (!rawSessionToken) return null;
  const tokenHash = await sha256(rawSessionToken);
  const { data: session, error } = await supabase
    .from('laundry_route_sessions')
    .select(`
      id,
      expires_at,
      revoked_at,
      laundry_route_workers!inner(
        id,
        cleaner_id,
        sede_id,
        is_active,
        cleaners!inner(id, name, is_active)
      )
    `)
    .eq('share_link_id', shareLinkId)
    .eq('token_hash', tokenHash)
    .is('revoked_at', null)
    .gt('expires_at', new Date().toISOString())
    .maybeSingle();

  if (error) throw error;
  const routeWorker = singleRelation(session?.laundry_route_workers as any);
  const cleaner = singleRelation(routeWorker?.cleaners as any);
  if (!session || !routeWorker?.is_active || !cleaner?.is_active) return null;

  await supabase
    .from('laundry_route_sessions')
    .update({ last_seen_at: new Date().toISOString() })
    .eq('id', session.id);

  return {
    routeWorkerId: String(routeWorker.id),
    cleanerId: String(routeWorker.cleaner_id),
    workerName: String(cleaner.name),
    sedeId: String(routeWorker.sede_id),
  };
}
